    {
        "name": "Caparinia Mange (Severe)",
        "name_ja": "カパリニアダニ症（重症型）",
        "symptoms": {"pruritus", "severe_quill_loss", "skin_flaking", "thick_crusting", "weight_loss"},
        "description": "アフリカンピグミーハリネズミは真の冬眠ができず、低体温性嗜眠は生命を脅かします。体温が危険なほど低下します。",
        "description_ja": "カパリニア・トリピリスの重度寄生で、広範な針の脱落、厚い痂皮、二次細菌感染を引き起こします。",
        "urgency": "high",
        "recommended_tests": ["skin_scraping", "microscopy", "physical_exam"],
        "causes": "Heavy Caparinia tripilis mite infestation causing extensive quill loss, thick crusts, and secondary bacterial infection.",
        "causes_ja": "ハリネズミにおけるカパリニアダニ症（重症型）の原因: カパリニア・トリピリスの重度寄生で、広範な針の脱落、厚い痂皮、二次細菌感染を引き起こします。",
        "pathophysiology": "Heavy Caparinia tripilis mite infestation causing extensive quill loss, thick crusts, and secondary bacterial infection. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "カパリニアダニ症（重症型）はハリネズミにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "",
        "treatment_ja": "ハリネズミにおけるカパリニアダニ症（重症型）の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "カパリニアダニ症（重症型）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prevention_ja": "カパリニアダニ症（重症型）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "",
        "prognosis_ja": "カパリニアダニ症（重症型）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
    {
        "name": "Quill Mites (Chorioptes)",
        "name_ja": "針ダニ（コリオプテス）",
        "symptoms": {"dandruff", "dry_flaky_skin", "mild_itching", "quill_loss"},
        "description": "表面寄生性ダニで軽度の針の脱落と鱗屑を引き起こします。カパリニアほど重度ではありませんが治療が必要です。",
        "description_ja": "表面寄生性ダニで軽度の針の脱落と鱗屑を引き起こします。カパリニアほど重度ではありませんが治療が必要です。",
        "urgency": "moderate",
        "recommended_tests": ["skin_scraping", "microscopy", "tape_test"],
        "causes": "ハリネズミにおける針ダニ（コリオプテス）の原因: 表面寄生性ダニで軽度の針の脱落と鱗屑を引き起こします。カパリニアほど重度ではありませんが治療が必要です。",
        "causes_ja": "ハリネズミにおける針ダニ（コリオプテス）の原因: 表面寄生性ダニで軽度の針の脱落と鱗屑を引き起こします。カパリニアほど重度ではありませんが治療が必要です。",
        "pathophysiology": "カパリニアダニ症（重症型）はハリネズミにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "pathophysiology_ja": "針ダニ（コリオプテス）はハリネズミにおける寄生虫疾患である。寄生虫は経口摂取、経皮的侵入、またはベクター媒介伝播を通じて感染を確立する。抗原変異、免疫調節、細胞内隔離により宿主の免疫防御を回避しながら、宿主の栄養と資源を利用して増殖する。組織損傷は寄生虫の直接的な摂食、機械的破壊、有毒代謝副産物、宿主の炎症・免疫応答に起因する。重度の寄生虫感染は貧血、栄養失調、臓器機能障害、二次感染を引き起こしうる。",
        "treatment": "ハリネズミにおける針ダニ（コリオプテス）の治療には、同定された寄生虫に応じた適切な駆虫薬が必要である。一部の駆虫薬は特定の種に有毒であるため、種に適した用量設定が重要である。全てのライフステージを排除するため複数回投与が必要な場合がある。環境消毒と接触動物の治療で再感染を防止する。貧血、脱水、栄養失調などの二次的合併症に対する支持療法を行う。",
        "treatment_ja": "ハリネズミにおける針ダニ（コリオプテス）の治療には、同定された寄生虫に応じた適切な駆虫薬が必要である。一部の駆虫薬は特定の種に有毒であるため、種に適した用量設定が重要である。全てのライフステージを排除するため複数回投与が必要な場合がある。環境消毒と接触動物の治療で再感染を防止する。貧血、脱水、栄養失調などの二次的合併症に対する支持療法を行う。",
        "prevention": "カパリニアダニ症（重症型）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prevention_ja": "針ダニ（コリオプテス）の予防には定期的な予防駆虫、環境衛生と糞便除去、新規動物の隔離・検査、ベクター防除、中間宿主や汚染環境への曝露回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "針ダニ（コリオプテス）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
